import json,pathlib
R=pathlib.Path(__file__).resolve().parents[1]
summaries=json.loads((R/'content/summaries.json').read_text())
catalog=json.loads((R/'content/catalog.json').read_text())
template=r'''(()=>{'use strict';
const DATA=__DATA__,SUMMARIES=__SUMMARIES__;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function element(html){const t=document.createElement('template');t.innerHTML=html.trim();return t.content.firstElementChild}
const heading=(label,title,lead)=>`<span class="to-eyebrow">${esc(label)}</span><h2 class="to-title">${esc(title)}</h2><p class="to-lead">${esc(lead)}</p>`;
function summarySection(){return element(`<section id="resumos-completos" class="to-study" aria-labelledby="to-study-heading">${heading('Terapia Ocupacional · resumos para estudar','Abra seu caderno. A revisão começa aqui.','Cinco resumos completos para conectar os fundamentos às situações da faculdade. Leia as explicações, compare as tabelas, percorra os mapas de conceitos e responda às perguntas de revisão.')}<nav class="to-jumps" aria-label="Ir para um resumo">${SUMMARIES.map(s=>`<a href="#resumo-${s.id}">${s.number}. ${esc(s.title)}</a>`).join('')}</nav><p class="to-study-status" aria-live="polite"></p>${SUMMARIES.map(s=>`<article class="to-summary" id="resumo-${s.id}" aria-labelledby="resumo-titulo-${s.id}"><header><span>Meu caderno de Terapia Ocupacional · resumo ${s.number}/5</span><h2 id="resumo-titulo-${s.id}">${esc(s.title)}</h2><p>${esc(s.subtitle)}</p></header><div class="to-summary-body">${s.body}</div><footer><button type="button" data-read="${s.id}" aria-pressed="false">Marcar como revisado</button></footer></article>`).join('')}</section>`)}
function curriculum(){const groups=[...new Set(DATA.disciplines.map(d=>d[1]))];return element(`<section class="to-curriculum" id="disciplinas-terapia">${heading('Disciplinas de Terapia Ocupacional','As matérias da sua graduação, assunto por assunto.','Libras, fisiologia, neuroanatomia, desenvolvimento, recursos terapêuticos, saúde mental e outros conteúdos para acompanhar suas aulas. Explore os temas de cada disciplina e encontre o que deseja revisar. As denominações variam entre instituições.')}<div class="to-filters" role="group" aria-label="Filtrar disciplinas"><button type="button" data-group="Todas" aria-pressed="true">Todas as disciplinas</button>${groups.map(g=>`<button type="button" data-group="${esc(g)}" aria-pressed="false">${esc(g)}</button>`).join('')}</div><p class="to-course-status" aria-live="polite">${DATA.disciplines.length} disciplinas para explorar</p><div class="to-course-grid">${DATA.disciplines.map(d=>`<article class="to-course" data-course-group="${esc(d[1])}"><span>${esc(d[1])}</span><h3>${esc(d[0])}</h3><ul>${d[2].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></article>`).join('')}</div></section>`)}
function bibliography(){return element(`<section class="to-reference" id="base-teorica-terapia">${heading('Biblioteca de referências','Uma base teórica para sustentar o que você escreve.','Vinte referências de livros, documentos profissionais e políticas públicas, organizadas por assunto e no formato bibliográfico da ABNT. Cada cartão mostra a obra, os temas relacionados e uma forma de chamada autor-data para acompanhar a sua leitura.')}<div class="to-ref-grid">${DATA.references.map((r,i)=>`<article class="to-ref-card"><span class="to-eyebrow">${esc(r[0])}</span><h3>${esc(r[0])}</h3><blockquote id="to-ref-${i}">${esc(r[1])}</blockquote><p><strong>Para estudar:</strong> ${esc(r[2])}</p><span class="to-cite">Chamada autor-data: ${esc(r[3])}</span><button type="button" data-copy="${i}">Copiar referência</button></article>`).join('')}</div><p class="to-study-status" aria-live="polite"></p></section>`)}
function planner(){return element(`<section class="to-planner" id="plano-estudo-terapia">${heading('Plano de estudos preenchido','Uma semana de estudo com começo, revisão e retomada.','Exemplo para uma semana com avaliação de fundamentos e discussão de caso na infância. Os blocos combinam leitura, recuperação da memória, perguntas e aplicação. Ajuste o tempo ao seu calendário e às dificuldades que aparecerem.')}<div class="to-week"><article class="to-day"><h3>Segunda · compreender os fundamentos</h3><p><strong>45 minutos · ocupação, atividade e participação</strong></p><ul><li>20 min: ler o resumo e elaborar um exemplo de cada conceito.</li><li>15 min: responder cinco flashcards sem consultar a resposta.</li><li>10 min: registrar duas dúvidas e retomar o trecho correspondente.</li></ul></article><article class="to-day"><h3>Terça · relacionar ao cotidiano</h3><p><strong>50 minutos · infância e adolescência</strong></p><ul><li>20 min: estudar desenvolvimento, brincar e participação escolar.</li><li>20 min: analisar o caso da organização da mochila.</li><li>10 min: explicar por que autonomia não equivale a independência física.</li></ul></article><article class="to-day"><h3>Quinta · aplicar o raciocínio</h3><p><strong>45 minutos · análise de atividade e comunicação</strong></p><ul><li>15 min: descrever etapas e exigências de uma atividade cotidiana.</li><li>20 min: propor uma graduação e uma adaptação, justificando a diferença.</li><li>10 min: rever os cartões que exigiram consulta.</li></ul></article><article class="to-day"><h3>Sábado · recuperar e comparar</h3><p><strong>60 minutos · revisão integrada</strong></p><ul><li>20 min: escrever de memória um mapa com os conceitos da semana.</li><li>20 min: responder às perguntas dos resumos e comparar as explicações.</li><li>20 min: relacionar um caso a objetivos, contexto, estratégias e reavaliação.</li></ul></article></div><div class="to-plan-path" aria-label="Exemplo de retomadas"><span>Primeira leitura</span><span>Retomada no dia seguinte</span><span>Nova revisão em 3–7 dias</span><span>Aplicação em outro caso</span></div><p class="to-lead">Ao final da semana, priorize o que ainda não consegue explicar com clareza. A próxima revisão pode retomar menos conteúdos e aprofundar as relações que ficaram difíceis.</p></section>`)}
function game(){return element(`<div class="to-game" role="region" aria-label="Jogo de flashcards de Terapia Ocupacional"><h3>Seu desafio de Terapia Ocupacional</h3><p class="to-game-copy">Ocupação, desenvolvimento, SUS, ética e recursos terapêuticos: leia a pergunta, formule sua explicação e revele a resposta. Marque o que lembrou e volte aos assuntos que merecem outra revisão.</p><div class="to-game-top"><span data-game-topic></span><span data-game-count></span></div><div class="to-game-question" data-game-question></div><div class="to-game-answer" data-game-answer hidden aria-live="polite"></div><div class="to-game-actions"><button type="button" data-action="reveal" aria-expanded="false">Revelar resposta</button><button type="button" data-action="remember" hidden>Lembrei desta</button><button type="button" data-action="next">Próximo flashcard</button></div><progress max="20" value="0" aria-label="Flashcards marcados como lembrados"></progress><p class="to-remember" aria-live="polite"></p></div>`)}
function tccExample(){return element(`<div class="to-tcc-example"><h3>Do assunto à pergunta: um exemplo de TCC em Terapia Ocupacional</h3><p><strong>Tema:</strong> participação escolar de adolescentes com deficiência. <strong>Recorte:</strong> barreiras e apoios descritos na literatura para a organização da rotina escolar.</p><p><strong>Pergunta:</strong> quais barreiras e facilitadores da participação na rotina escolar são descritos em estudos sobre adolescentes com deficiência?</p><p><strong>Objetivo geral:</strong> analisar barreiras e facilitadores descritos nos estudos selecionados. <strong>Objetivos específicos:</strong> caracterizar os contextos, identificar ocupações e atividades estudadas e organizar os apoios discutidos.</p><p><strong>Percurso de pesquisa:</strong> definir a pergunta com a orientação, escolher bases e descritores, estabelecer critérios de inclusão, registrar a seleção, extrair os dados e comparar os achados. A escolha entre revisão de escopo, integrativa ou outro método precisa corresponder à pergunta e ao protocolo adotado.</p><p><strong>Quadro de leitura preenchido:</strong> autor e ano → contexto escolar → participantes → barreiras ambientais e sociais → apoios → resultados e limites. Na escrita, diferencie o que os estudos demonstram da interpretação construída na análise.</p></div>`)}
function mount(){const main=document.querySelector('main');if(!main||main.querySelector('#resumos-completos'))return !!main?.querySelector('#resumos-completos');const sections=[...main.children].filter(e=>e.tagName==='SECTION');if(sections.length<10||!sections[1]?.querySelector('h2')||!document.getElementById('caderno-preenchido')||!document.getElementById('fichas-para-revisar'))return false;
const originalSummary=sections[1];originalSummary.replaceWith(summarySection());main.querySelector('#resumos-completos .to-title').id='to-study-heading';
const audience=sections.find(e=>e.textContent.includes('Para quem é o caderno.'));if(audience)audience.classList.add('to-audience');
const areas=sections.find(e=>e.querySelector('h2')?.textContent.includes('Grandes áreas da Terapia Ocupacional'));if(areas){areas.id='resumos-por-assunto';areas.querySelector('h2').textContent='Mais de 2.600 resumos completos';const intro=areas.querySelector('h2')?.parentElement?.querySelector('p');if(intro)intro.textContent='Fundamentos, avaliação, infância, saúde mental, reabilitação e participação social. Compare conceitos e veja como os assuntos se conectam às situações estudadas na faculdade.';}
const focus=document.getElementById('resumos-em-foco');if(focus){focus.querySelector('h2').textContent='Mais de 2.600 resumos completos';focus.querySelector('.exam-opening header>p').textContent='Brincar e participação escolar, análise de atividades, atenção psicossocial e tecnologia assistiva: conceitos e exemplos para acompanhar as matérias da sua graduação.';const topics=[['Brincar e participação escolar','Brincar envolve exploração, autoria, relações e regras. Na escola, a participação inclui comunicação, aprendizagem, recreio e pertencimento. A análise conecta interesses, demandas da tarefa e barreiras do ambiente.'],['Análise e adaptação de atividades','Descreva etapas, materiais, espaço e exigências. Graduar altera a demanda; adaptar reorganiza condições para ampliar participação. A escolha se relaciona ao objetivo e precisa ser acompanhada no contexto de uso.'],['Saúde mental e cotidiano','Rotinas, vínculos, circulação e projetos de vida fazem parte da análise. O cuidado em liberdade articula direitos, rede de suporte e oportunidades de participação, considerando o que importa para a pessoa.'],['Tecnologia assistiva em contexto','A escolha de um recurso considera objetivo, preferências, conforto, ambiente e manutenção. A avaliação acompanha o uso real: disponibilidade de uma ferramenta não garante que ela amplie a participação.']];focus.querySelectorAll('.exam-study-card').forEach((card,i)=>{if(!topics[i])return;const title=card.querySelector('h4'),answer=card.querySelector('.exam-answer p');if(title)title.textContent=topics[i][0];if(answer)answer.textContent=topics[i][1];});focus.querySelector('.exam-cards-heading h3').textContent='Assuntos que conectam teoria e cotidiano.';}
const oldGrade=sections.find(e=>e.querySelector('h2')?.textContent.includes('Grade do curso'));if(oldGrade){const courses=curriculum();oldGrade.replaceWith(courses);const refs=bibliography(),plan=planner();const filled=document.getElementById('caderno-preenchido');if(filled)filled.after(courses);courses.after(refs);refs.after(plan);}
const flash=sections.find(e=>e.querySelector('h2')?.textContent.includes('Veja os flashcards'));if(flash){flash.id='flashcards-terapia';flash.querySelector('h2').textContent='Mais de 1.520 flashcards para estudar Terapia Ocupacional';const intro=flash.querySelector('h2').parentElement.querySelector('p');if(intro)intro.textContent='Perguntas de desenvolvimento, avaliação, atividades terapêuticas, políticas públicas e ética para testar o que você lembra e aprofundar as respostas.';}
const lined=document.getElementById('fichas-para-revisar');if(lined){lined.querySelector('h2').textContent='Mais de 1.520 flashcards para estudar';lined.querySelector('header>p').textContent='Desenvolvimento, avaliação, atividades terapêuticas, políticas públicas e ética: revise os conceitos e pratique explicar o raciocínio com suas próprias palavras.';const g=game();lined.querySelector('header').after(g);initGame(g);lined.querySelectorAll('.lined-flash-card').forEach((card,i)=>{const f=DATA.flashcards[i%DATA.flashcards.length];const h=card.querySelector('h3'),p=card.querySelector('div p'),tab=card.querySelector('.lined-flash-tab');if(h)h.textContent=f[1];if(p)p.textContent=f[2];if(tab)tab.textContent=f[0];});}
const sample=sections.find(e=>e.querySelector('h2')?.textContent==='Amostra do caderno.');if(sample){const intro=sample.querySelector('h2').parentElement.querySelector('p');if(intro)intro.textContent='Acompanhe exemplos de resumo, flashcards, plano de estudos e organização de pesquisa em Terapia Ocupacional. As páginas conectam conceitos, perguntas e situações do cotidiano.';}
const tcc=sections.find(e=>e.querySelector('h2')?.textContent.includes('Três modelos de TCC'));if(tcc)tcc.querySelector('h2').parentElement.after(tccExample());
main.querySelectorAll('[data-read]').forEach(b=>b.addEventListener('click',()=>{const value=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(value));b.textContent=value?'Revisado · marcar para retomar':'Marcar como revisado';main.querySelector('.to-study-status').textContent=`${main.querySelectorAll('[data-read][aria-pressed=true]').length} de 5 resumos marcados como revisados nesta visita.`;}));
main.querySelectorAll('[data-group]').forEach(b=>b.addEventListener('click',()=>{const g=b.dataset.group;main.querySelectorAll('[data-group]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelectorAll('[data-course-group]').forEach(x=>x.hidden=g!=='Todas'&&x.dataset.courseGroup!==g);main.querySelector('.to-course-status').textContent=`${main.querySelectorAll('[data-course-group]:not([hidden])').length} disciplinas exibidas`;}));
main.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const value=DATA.references[Number(b.dataset.copy)][1];try{await navigator.clipboard.writeText(value);b.textContent='Referência copiada';}catch{const text=document.getElementById('to-ref-'+b.dataset.copy);const range=document.createRange();range.selectNodeContents(text);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);b.closest('section').querySelector('[aria-live]').textContent='Referência selecionada. Use a opção de copiar do seu dispositivo.';}}));
return true;}
function initGame(g){let pos=0;const known=new Set();const topic=g.querySelector('[data-game-topic]'),count=g.querySelector('[data-game-count]'),q=g.querySelector('[data-game-question]'),a=g.querySelector('[data-game-answer]'),reveal=g.querySelector('[data-action=reveal]'),remember=g.querySelector('[data-action=remember]');function draw(){const card=DATA.flashcards[pos];topic.textContent=card[0];count.textContent=`Cartão ${pos+1} de ${DATA.flashcards.length}`;q.textContent=card[1];a.textContent=card[2];a.hidden=true;remember.hidden=true;reveal.setAttribute('aria-expanded','false');reveal.textContent='Revelar resposta';g.querySelector('progress').max=DATA.flashcards.length;g.querySelector('progress').value=known.size;g.querySelector('.to-remember').textContent=`${known.size} de ${DATA.flashcards.length} cartões lembrados nesta rodada.`;}reveal.addEventListener('click',()=>{a.hidden=!a.hidden;remember.hidden=a.hidden;reveal.setAttribute('aria-expanded',String(!a.hidden));reveal.textContent=a.hidden?'Revelar resposta':'Ocultar resposta';});remember.addEventListener('click',()=>{known.add(pos);g.querySelector('progress').value=known.size;g.querySelector('.to-remember').textContent=`${known.size} de ${DATA.flashcards.length} cartões lembrados nesta rodada.`;remember.textContent='Marcado como lembrado';});g.querySelector('[data-action=next]').addEventListener('click',()=>{pos=(pos+1)%DATA.flashcards.length;remember.textContent='Lembrei desta';draw();});draw();}
if(!mount()){const o=new MutationObserver(()=>{if(mount())o.disconnect()});o.observe(document.getElementById('root')||document.body,{childList:true,subtree:true});}
})();'''
(R/'assets/study-refresh.js').write_text(template.replace('__DATA__',json.dumps(catalog,ensure_ascii=False)).replace('__SUMMARIES__',json.dumps(summaries,ensure_ascii=False)))
print('study-refresh.js gerado')
